/* Cybersecurity — L3 Sicurezza applicativa e web: 6 lezioni approfondite (solo difesa). */
(function (ST) {
  'use strict';
  const C = ST.content, { mc, fill, order } = C;
  // Helper: inserisce la risposta giusta nella posizione voluta.
  const M = (q, right, wrong, pos, why) => { const o = wrong.slice(); o.splice(pos, 0, right); return mc(q, o, pos, why); };

  /* ---------- 1 · HTTP, sessioni e cookie ---------- */
  C.addTopic({
    id: 'cyb-http-sessioni-e-cookie', subject: 'cyb', stage: 'L3', minutes: 12,
    title: 'HTTP, sessioni e cookie',
    summary: 'Come funziona HTTP, come si gestiscono sessioni e cookie in modo sicuro, e perché same-origin policy e CORS contano.',
    objectives: ['Descrivere richieste, metodi e codici di stato HTTP', 'Configurare i cookie di sessione con HttpOnly, Secure e SameSite', 'Spiegare same-origin policy, CORS e le insidie dei token JWT'],
    pages: [
      { h: 'HTTP: richiesta e risposta', b: `**HTTP** è un protocollo **senza stato**: ogni richiesta è indipendente e il server, da solo, non ricorda chi sei. Il client invia una **richiesta** (metodo, percorso, intestazioni, eventuale corpo) e riceve una **risposta** (codice di stato, intestazioni, corpo).\n\nI metodi principali:\n\n- **GET**: legge una risorsa, non dovrebbe modificare dati (è «sicuro» e idempotente).\n- **POST**: crea o invia dati, non è idempotente.\n- **PUT** / **PATCH**: sostituisce o modifica; **DELETE**: elimina.\n\nPer la sicurezza conta una regola: **un GET non deve mai cambiare lo stato** del sistema, perché può essere richiamato da link, precaricamenti e immagini.\n\n> Sbagliato: GET /conto/trasferisci?a=123&importo=50\n> Corretto: POST /conto/trasferisci con corpo e protezione anti-CSRF\n\nI dati sensibili non vanno mai messi nell’URL: finisce nei log, nella cronologia e nell’intestazione Referer.` },
      { h: 'Codici di stato e intestazioni', b: `Il **codice di stato** riassume l’esito, in cinque famiglie:\n\n- **2xx** successo (200 OK, 201 Created, 204 No Content);\n- **3xx** reindirizzamento (301, 302, 304);\n- **4xx** errore del client (400 richiesta errata, **401** non autenticato, **403** non autorizzato, 404 non trovato, 429 troppe richieste);\n- **5xx** errore del server (500, 502, 503).\n\nDifferenza chiave: **401** = «non so chi sei», **403** = «so chi sei, ma non puoi».\n\nIntestazioni di sicurezza utili nelle risposte:\n\n- **Strict-Transport-Security** (HSTS): obbliga il browser a usare HTTPS;\n- **X-Content-Type-Options: nosniff**: impedisce di reinterpretare il tipo di file;\n- **Content-Security-Policy** e **frame-ancestors**: limitano script e incorporamento;\n- **Cache-Control: no-store** per pagine con dati personali.\n\nI messaggi d’errore non devono rivelare percorsi interni, versioni o stack trace.` },
      { h: 'Cookie e i tre flag fondamentali', b: `Poiché HTTP non ha stato, il server assegna al browser un **cookie** che torna a ogni richiesta. Un cookie di sessione va protetto con tre attributi:\n\n- **HttpOnly**: il cookie non è leggibile da JavaScript; riduce il furto di sessione dopo un XSS.\n- **Secure**: viene inviato solo su HTTPS, mai in chiaro.\n- **SameSite** (Strict, Lax, None): limita l’invio nelle richieste originate da altri siti; difende da CSRF. **Lax** è un buon valore predefinito; **None** richiede Secure.\n\nAltri attributi: **Path**, **Domain** (restringili il più possibile), **Max-Age** o **Expires** (scadenza). Il prefisso **__Host-** impone Secure, Path=/ e nessun Domain.\n\n> VULNERABILE: Set-Cookie: sid=abc123\n> CORRETTO: Set-Cookie: __Host-sid=abc123; Secure; HttpOnly; SameSite=Lax; Path=/\n\nOgni flag mancante è una porta lasciata socchiusa.` },
      { h: 'Gestione delle sessioni', b: `Una sessione sicura segue regole precise:\n\n- **Identificatore casuale e lungo**, generato da un generatore crittograficamente sicuro (almeno 128 bit di entropia), mai prevedibile né derivato da dati dell’utente.\n- **Rigenerazione dell’ID al login** e a ogni cambio di privilegio: previene la **session fixation**, in cui l’attaccante impone un ID noto alla vittima.\n- **Scadenza** per inattività e scadenza assoluta; **logout** che invalida la sessione **sul server**, non solo cancellando il cookie.\n- L’ID non compare mai nell’URL.\n- Lo stato resta sul server: il cookie contiene solo un riferimento opaco.\n\n> VULNERABILE: dopo il login si riusa lo stesso session ID di prima\n> CORRETTO: dopo il login si crea un nuovo ID e si distrugge il vecchio\n\nPer operazioni critiche (cambio password, pagamenti) conviene una **ri-autenticazione** e la notifica all’utente.` },
      { h: 'Token e JWT: le insidie', b: `Un **JWT** (JSON Web Token) è un token firmato composto da intestazione, contenuto (claim) e firma. Attenzione: è **firmato, non cifrato** di default. Chiunque lo possieda legge i claim, quindi non vi vanno dati riservati.\n\nErrori frequenti a livello concettuale:\n\n- **non verificare la firma** o accettare l’algoritmo «none»; il server deve imporre l’algoritmo atteso;\n- scegliere **segreti deboli** per firme simmetriche;\n- **non controllare** scadenza (exp), emittente (iss) e destinatario (aud);\n- token **a lunga durata** non revocabili: se rubato, vale fino alla scadenza;\n- conservarlo in **localStorage**, leggibile da qualunque script iniettato.\n\nBuone pratiche: scadenze brevi con **refresh token** ruotati, revoca lato server, conservazione in cookie HttpOnly e Secure, librerie consolidate invece di codice fatto in casa.\n\nUn JWT non è «più sicuro» di una sessione server-side: ha compromessi diversi, soprattutto sulla revoca.` },
      { h: 'Same-origin policy', b: `Un’**origine** è la terna **schema + host + porta**. La **same-origin policy** (SOP) è la regola del browser per cui una pagina può **leggere** liberamente solo risorse della propria origine.\n\n> https://app.esempio.it e https://app.esempio.it:443/altro → stessa origine\n> http://app.esempio.it → origine diversa (schema)\n> https://api.esempio.it → origine diversa (host)\n> https://app.esempio.it:8443 → origine diversa (porta)\n\nLa SOP impedisce che lo script di un sito malevolo legga la tua casella webmail aperta in un’altra scheda. **Non impedisce** di inviare richieste verso altri siti (per questo esiste il CSRF) e non protegge il server: è una difesa del **browser**, non un controllo di accesso.\n\nI cookie seguono regole proprie, basate su dominio e percorso, non sull’origine: è un’ulteriore ragione per usare SameSite.` },
      { h: 'CORS e le sue errate configurazioni', b: `Il **CORS** (Cross-Origin Resource Sharing) permette al server di **allentare** la SOP in modo controllato, tramite intestazioni come **Access-Control-Allow-Origin**. Non è un meccanismo di protezione aggiuntivo: è un’eccezione concessa.\n\nErrori tipici:\n\n- **Allow-Origin: *** su API che restituiscono dati riservati;\n- **riflettere l’intestazione Origin** della richiesta senza controllarla, abbinata ad **Allow-Credentials: true**: qualunque sito potrebbe leggere dati dell’utente autenticato;\n- fidarsi di origini «null» o di pattern troppo larghi (sottodomini non controllati);\n- credere che il CORS sostituisca autenticazione e autorizzazione.\n\n> VULNERABILE: Access-Control-Allow-Origin = valore di Origin ricevuto; Allow-Credentials: true\n> CORRETTO: confronto con una **lista chiusa** di origini fidate; solo quelle ricevono l’intestazione\n\nRegola: elenco esplicito, nessun carattere jolly con credenziali, e controlli di accesso sempre sul server.` }
    ],
    exercises: [
      M('Quale metodo HTTP NON dovrebbe mai modificare lo stato del server?', 'GET', ['POST', 'DELETE', 'PUT'], 0, 'GET è «sicuro»: può essere richiamato da link e precaricamenti, quindi non deve cambiare dati.'),
      M('Un utente autenticato tenta di aprire una pagina riservata agli amministratori. Quale codice è più appropriato?', '403 Forbidden', ['401 Unauthorized', '404 Not Found', '200 OK'], 0, '401 significa non autenticato; 403 significa identificato ma non autorizzato.'),
      M('Quale cookie è configurato meglio?', 'Set-Cookie: sid=x9f; Secure; HttpOnly; SameSite=Lax', ['Set-Cookie: sid=x9f', 'Set-Cookie: sid=x9f; Path=/', 'Set-Cookie: sid=x9f; Max-Age=999999999'], 2, 'Solo questa versione ha i tre flag di protezione fondamentali.'),
      fill('Quale attributo del cookie lo rende illeggibile da JavaScript? (una parola)', ['HttpOnly', 'httponly'], 'HttpOnly impedisce a document.cookie di leggere il cookie.'),
      M('Quale frammento di logica di login è vulnerabile alla session fixation?', 'Dopo l’autenticazione si continua a usare lo stesso ID di sessione precedente', ['Dopo l’autenticazione si genera un nuovo ID e si invalida il vecchio', 'L’ID è generato con un generatore casuale sicuro', 'La sessione ha una scadenza per inattività'], 0, 'Un ID imposto prima del login resterebbe valido dopo: va rigenerato.'),
      M('Quale coppia di URL ha la STESSA origine?', 'https://a.it/x e https://a.it/y?z=1', ['https://a.it e http://a.it', 'https://a.it e https://api.a.it', 'https://a.it e https://a.it:8443'], 1, 'Origine = schema + host + porta; il percorso non conta.'),
      M('Quale configurazione CORS è corretta per un’API con cookie di sessione?', 'Confronto con una lista chiusa di origini fidate', ['Allow-Origin: * con Allow-Credentials: true', 'Riflettere sempre l’intestazione Origin ricevuta', 'Accettare qualunque sottodominio tramite pattern generico'], 0, 'La lista chiusa è l’unica scelta che non espone dati ad origini arbitrarie.'),
      M('Cosa è vero riguardo a un JWT firmato?', 'I claim sono leggibili da chi lo possiede: non vi si mettono dati riservati', ['I claim sono cifrati e quindi segreti', 'Non serve controllare la scadenza se la firma è valida', 'È revocabile istantaneamente senza stato sul server'], 0, 'La firma garantisce l’integrità, non la riservatezza.'),
      fill('Come si chiama l’attacco in cui l’ID di sessione viene imposto alla vittima prima del login? (due parole in inglese)', ['session fixation', 'Session Fixation'], 'Si previene rigenerando l’ID dopo l’autenticazione.'),
      order('Ordina i passi corretti per gestire il login in modo sicuro', ['Verifica credenziali', 'poi', 'nuovo ID di sessione', 'cookie Secure HttpOnly', 'scadenza impostata'], 'Credenziali, rigenerazione dell’ID, cookie con flag, scadenza.')
    ],
    test: [
      M('Quale intestazione costringe il browser a usare solo HTTPS per un sito?', 'Strict-Transport-Security', ['X-Frame-Options', 'Cache-Control', 'Content-Length'], 0, 'HSTS indica di usare sempre HTTPS.'),
      M('Perché i dati sensibili non vanno inseriti nell’URL?', 'Finiscono in log, cronologia e intestazione Referer', ['Gli URL sono sempre cifrati', 'Il server li ignora', 'Rallentano la risposta'], 0, 'L’URL viene registrato in molti punti.'),
      fill('Che famiglia di codici di stato indica un errore del server? (es. 5xx: scrivi solo la cifra iniziale)', ['5'], 'I codici 5xx indicano errori lato server.'),
      M('Quale affermazione sul logout sicuro è corretta?', 'Invalida la sessione sul server, non solo il cookie nel browser', ['Basta cancellare il cookie lato client', 'Non serve se la sessione scade', 'Basta reindirizzare alla home'], 0, 'Un cookie copiato resterebbe valido se il server non invalida la sessione.'),
      M('La same-origin policy è una difesa che agisce principalmente…', 'nel browser, limitando la lettura di risposte di altre origini', ['sul firewall di rete', 'nel database', 'nel sistema operativo del server'], 0, 'È una regola applicata dal browser.'),
      M('Quale errore rende pericoloso un token JWT?', 'Accettare token senza verificare firma e scadenza', ['Usare una libreria consolidata', 'Impostare una scadenza breve', 'Controllare iss e aud'], 0, 'Senza verifiche il token può essere falsificato o riusato.'),
      fill('Quale valore di SameSite è un buon predefinito per i cookie di sessione? (una parola)', ['Lax', 'lax'], 'Lax blocca l’invio nelle richieste cross-site non di navigazione sicura.')
    ]
  });

  /* ---------- 2 · OWASP Top 10 ---------- */
  C.addTopic({
    id: 'cyb-owasp-top10-panoramica', subject: 'cyb', stage: 'L3', minutes: 12,
    title: 'OWASP Top 10: panoramica',
    summary: 'Le dieci categorie di rischio più diffuse nelle applicazioni web e la difesa essenziale per ciascuna.',
    objectives: ['Spiegare cos’è la OWASP Top 10 e come si usa', 'Riconoscere le categorie di rischio principali', 'Associare a ogni categoria una difesa tipica'],
    prereq: ['cyb-http-sessioni-e-cookie'],
    pages: [
      { h: 'Che cos’è la OWASP Top 10', b: `**OWASP** (Open Worldwide Application Security Project) è una fondazione no profit che produce materiali aperti sulla sicurezza applicativa. La **Top 10** è un documento di **sensibilizzazione**: elenca le dieci categorie di rischio più critiche per le applicazioni web, ricavate da dati di test reali e da sondaggi tra esperti, e viene aggiornata periodicamente.\n\nCosa **è**: una lista di categorie ampie, un punto di partenza per formare gli sviluppatori e per impostare priorità.\n\nCosa **non è**: non è uno standard di conformità completo, non è un elenco esaustivo di tutte le vulnerabilità, non è una checklist da «spuntare».\n\nPer una verifica sistematica si usa invece **ASVS** (Application Security Verification Standard), che contiene requisiti verificabili. Ogni categoria della Top 10 raccoglie molte debolezze specifiche (classificate con identificativi **CWE**).` },
      { h: 'Accessi e crittografia', b: `**Broken Access Control (controllo degli accessi violato)**: l’utente riesce ad agire oltre i propri permessi, per esempio leggendo dati altrui. Difesa: autorizzazione **lato server** a ogni richiesta, con rifiuto per impostazione predefinita (deny by default).\n\n**Cryptographic Failures (fallimenti crittografici)**: dati sensibili esposti per cifratura assente o debole, chiavi gestite male, algoritmi obsoleti. Difesa: TLS ovunque, algoritmi e librerie moderne, password con hash lento e salt, gestione sicura delle chiavi, non conservare ciò che non serve.\n\n**Injection**: dati non fidati interpretati come comandi (SQL, sistema operativo, LDAP, XSS). Difesa: query parametrizzate, codifica dell’output, validazione.\n\n**Insecure Design (progettazione insicura)**: mancano controlli già nella progettazione, non solo nel codice. Difesa: threat modelling, schemi di riferimento sicuri, test dei casi di abuso.` },
      { h: 'Configurazione e componenti', b: `**Security Misconfiguration (configurazione errata)**: impostazioni predefinite pericolose, servizi inutili attivi, account di default, messaggi d’errore verbosi, permessi troppo ampi nel cloud. Difesa: configurazioni **hardenizzate** e ripetibili, rimozione di ciò che non serve, verifiche automatiche.\n\n**Vulnerable and Outdated Components (componenti vulnerabili e obsoleti)**: librerie e framework con falle note, mai aggiornati. Difesa: inventario delle dipendenze, strumenti di analisi della composizione (SCA), aggiornamenti regolari, componenti solo da fonti ufficiali.\n\nQueste due categorie sono tra le più **comuni** perché non servono bug complessi nel proprio codice: bastano una configurazione trascurata o un aggiornamento rinviato.\n\n> Esempio di buona prassi: pipeline che blocca la build se una dipendenza ha una vulnerabilità grave nota senza correzione prevista.` },
      { h: 'Identità e integrità', b: `**Identification and Authentication Failures (errori di identificazione e autenticazione)**: password deboli ammesse, nessuna protezione dai tentativi ripetuti, sessioni non invalidate, recupero credenziali fragile. Difesa: **MFA**, limitazione dei tentativi, politiche di password moderne (lunghezza, controllo contro elenchi di password note), gestione sicura delle sessioni.\n\n**Software and Data Integrity Failures (errori di integrità di software e dati)**: si accetta codice o dati senza verificarne l’origine, per esempio aggiornamenti non firmati, dipendenze da repository non fidati, deserializzazione di dati non attendibili, pipeline CI/CD non protette. Difesa: **firme digitali**, verifica dell’integrità, pipeline con controlli e permessi minimi, niente deserializzazione di dati non fidati.\n\nIl filo conduttore: **non fidarsi** di ciò che non si è verificato, che sia un utente, un pacchetto o un aggiornamento.` },
      { h: 'Log e richieste forgiate dal server', b: `**Security Logging and Monitoring Failures (errori di logging e monitoraggio)**: eventi rilevanti non registrati, log senza allarmi, nessuna correlazione. Un attacco in corso passa inosservato per mesi. Difesa: registrare accessi, errori di autorizzazione e modifiche importanti, centralizzare i log, definire allarmi e procedure di risposta. Ma **mai** registrare password, token o dati personali in chiaro.\n\n**Server-Side Request Forgery (SSRF)**: l’applicazione effettua richieste verso un indirizzo scelto dall’utente, e può essere indotta a raggiungere servizi interni non esposti (per esempio il servizio di metadati del cloud). Difesa: **lista consentita** di destinazioni, validazione e risoluzione degli indirizzi lato server, blocco degli intervalli di rete interni, segmentazione, nessuna risposta grezza restituita al client.\n\nNelle ultime edizioni la SSRF è stata inserita come categoria autonoma, a conferma dell’importanza delle architetture cloud.` },
      { h: 'Come si usa nella pratica', b: `La Top 10 serve a **dare priorità**, non a esaurire il lavoro.\n\n1. **Formazione**: usala come lessico comune tra sviluppatori, sistemisti e sicurezza.\n2. **Progettazione**: per ogni categoria chiediti «dove potrebbe capitare nel mio sistema?».\n3. **Test**: integra analisi statica, dinamica e verifica delle dipendenze, mappando i risultati sulle categorie.\n4. **Revisione**: inserisci le categorie nella checklist di code review.\n5. **Misura**: monitora quante falle per categoria emergono e con quale tempo di correzione.\n\n> Una vulnerabilità di SQL injection → categoria Injection; una dipendenza con falla nota → componenti vulnerabili; una funzione amministrativa raggiungibile da tutti → controllo degli accessi.\n\nNota di prudenza: la numerazione e i nomi cambiano tra edizioni, mentre i concetti restano. Consulta sempre l’edizione corrente sul sito ufficiale prima di citare posizioni in classifica.` },
      { h: 'Mappa rapida categoria → difesa', b: `Riepilogo da tenere a mente, una riga per categoria:\n\n- **Controllo accessi violato** → autorizzazione server-side, deny by default.\n- **Fallimenti crittografici** → TLS, algoritmi moderni, hash lento per le password.\n- **Injection** → query parametrizzate e codifica dell’output.\n- **Progettazione insicura** → threat modelling e casi di abuso.\n- **Configurazione errata** → hardening e automazione.\n- **Componenti vulnerabili** → inventario, SCA, aggiornamenti.\n- **Errori di autenticazione** → MFA, limiti ai tentativi, sessioni robuste.\n- **Errori di integrità** → firme e verifica di build e dipendenze.\n- **Errori di logging** → log utili, centralizzati, con allarmi.\n- **SSRF** → liste consentite e segmentazione di rete.\n\nSi nota che molte difese condividono principi: **minimo privilegio**, **difesa in profondità**, **sicuro per impostazione predefinita**, **non fidarsi dell’input**.` }
    ],
    exercises: [
      M('Qual è la funzione principale della OWASP Top 10?', 'Sensibilizzare e dare priorità alle categorie di rischio più critiche', ['Certificare che un’applicazione sia sicura', 'Elencare ogni singola vulnerabilità esistente', 'Sostituire i test di sicurezza'], 0, 'È un documento di consapevolezza, non uno standard di conformità né un elenco esaustivo.'),
      M('Un utente cambia l’identificativo nell’URL e legge i dati di un altro utente. Quale categoria?', 'Controllo degli accessi violato', ['Fallimenti crittografici', 'SSRF', 'Errori di logging'], 0, 'L’applicazione non verifica che la risorsa appartenga all’utente.'),
      M('Quale difesa è tipica per i fallimenti crittografici?', 'TLS, algoritmi moderni e hash lento con salt per le password', ['Nascondere il sito dai motori di ricerca', 'Limitare la dimensione delle immagini', 'Disabilitare i cookie'], 0, 'Si protegge dati in transito e a riposo con primitive moderne.'),
      fill('Come si chiama l’analisi che individua componenti con vulnerabilità note? (sigla di tre lettere)', ['SCA', 'sca'], 'Software Composition Analysis.'),
      M('L’applicazione scarica un’URL fornita dall’utente e può raggiungere servizi interni. Quale categoria?', 'SSRF', ['Injection SQL', 'Errori di integrità', 'Configurazione errata del browser'], 0, 'Server-Side Request Forgery: il server effettua richieste forgiate dall’esterno.'),
      M('Quale pratica contrasta meglio gli errori di integrità di software e dati?', 'Firmare e verificare aggiornamenti e dipendenze', ['Aumentare la dimensione dei log', 'Usare password più lunghe', 'Cambiare la porta del server'], 0, 'Senza verifica dell’origine si accetta codice non fidato.'),
      M('Quale caso rientra nella configurazione errata?', 'Account amministratore con la password predefinita ancora attiva', ['Query SQL costruite con concatenazione', 'Sessioni senza rigenerazione dell’ID', 'Libreria vecchia con falla nota'], 0, 'Le impostazioni predefinite pericolose sono configurazione errata.'),
      fill('Come si chiama la categoria in cui mancano controlli già nella fase di progetto? (due parole: Insecure ...)', ['Insecure Design', 'insecure design'], 'Non si risolve con una patch di codice: serve ripensare il progetto.'),
      M('Quale evento è corretto registrare nei log?', 'Tentativi di accesso falliti e rifiuti di autorizzazione', ['Le password inserite dagli utenti', 'I numeri completi delle carte di pagamento', 'I token di sessione in chiaro'], 0, 'Si registrano eventi utili senza dati segreti.'),
      order('Ordina il flusso d’uso della Top 10 in un team', ['Formazione', 'poi', 'progettazione', 'test', 'revisione e misura'], 'Dalla consapevolezza alla misura continua.')
    ],
    test: [
      M('Quale documento contiene requisiti verificabili per una verifica più sistematica?', 'ASVS', ['La sola Top 10', 'Il file robots.txt', 'Il certificato TLS'], 0, 'Application Security Verification Standard.'),
      M('Quale difesa è tipica contro gli errori di autenticazione?', 'Autenticazione a più fattori e limiti ai tentativi', ['Mostrare messaggi di errore dettagliati', 'Consentire password brevi', 'Allungare la scadenza delle sessioni senza limite'], 0, 'MFA e limiti rendono molto più difficile l’abuso di credenziali.'),
      fill('Quale principio impone di concedere solo i permessi strettamente necessari? (tre parole: minimo ...)', ['minimo privilegio', 'Minimo privilegio'], 'Il minimo privilegio riduce l’impatto di ogni compromissione.'),
      M('La Top 10 è…', 'un elenco di categorie, non una checklist esaustiva', ['una normativa obbligatoria per legge', 'un software di scansione', 'un elenco fisso che non cambia mai'], 0, 'Viene aggiornata e non esaurisce le vulnerabilità possibili.'),
      M('Una pipeline CI/CD senza controlli che compila codice da fonti non verificate ricade soprattutto in:', 'errori di integrità di software e dati', ['SSRF', 'fallimenti crittografici sui cookie', 'errori di codifica HTML'], 0, 'La catena di fornitura non è protetta da verifiche di integrità.'),
      M('Contro la SSRF è una difesa efficace…', 'una lista consentita di destinazioni raggiungibili dal server', ['un banner di avviso sul sito', 'la compressione delle risposte', 'cookie con SameSite'], 0, 'Limitando le destinazioni si evita di raggiungere servizi interni.'),
      fill('Quale principio prevede più livelli di protezione sovrapposti? (due parole: difesa in ...)', ['difesa in profondità', 'Difesa in profondità'], 'Se un livello cade, gli altri contengono il danno.')
    ]
  });

  /* ---------- 3 · Injection ---------- */
  C.addTopic({
    id: 'cyb-injection-e-prevenzione', subject: 'cyb', stage: 'L3', minutes: 12,
    title: 'Injection e prevenzione',
    summary: 'Perché nasce l’injection (dati mescolati al codice), come riconoscerla nel codice e come prevenirla alla radice.',
    objectives: ['Spiegare perché l’injection nasce dalla mescolanza tra dati e codice', 'Riconoscere pattern vulnerabili e correzioni nel codice', 'Applicare parametrizzazione, minimo privilegio e livelli di difesa'],
    prereq: ['cyb-owasp-top10-panoramica'],
    pages: [
      { h: 'La causa: dati trattati come codice', b: `Un’**injection** nasce quando un’applicazione costruisce un comando per un interprete (database, shell, directory, parser) **concatenando** dati non fidati nel testo del comando. L’interprete non distingue più ciò che il programmatore voleva come **struttura** da ciò che l’utente ha fornito come **dato**: tutto è una sola stringa, e il dato può cambiare il significato del comando.\n\nLa radice è sempre la stessa: **mescolanza di canale dati e canale di controllo**. Vale per SQL, comandi del sistema operativo, LDAP, XPath, NoSQL, modelli di pagina, intestazioni.\n\nPer questo la difesa robusta **non** consiste nel «ripulire» le stringhe cercando caratteri pericolosi, ma nel **mantenere separati** struttura e dati, in modo che l’interprete riceva i due elementi su canali distinti.\n\nL’impatto può essere grave: lettura o modifica di dati, bypass dell’autenticazione, esecuzione di comandi sul server. Per questo l’injection resta tra le categorie più critiche.` },
      { h: 'Riconoscerla nel codice SQL', b: `In una revisione del codice cerca ogni punto in cui una query viene costruita con **concatenazione o interpolazione** di stringhe che includono variabili provenienti dall’esterno (form, URL, intestazioni, file, altri servizi).\n\n> VULNERABILE:\n> query = "SELECT * FROM utenti WHERE email = '" + email + "'"\n> db.execute(query)\n\n> CORRETTO (query parametrizzata):\n> db.execute("SELECT * FROM utenti WHERE email = ?", [email])\n\nNella versione corretta il testo SQL è **fisso** e il valore viaggia separato: il database lo riceve come dato, mai come sintassi, qualunque contenuto abbia.\n\nSegnali d’allarme: stringhe SQL con più di una concatenazione, uso di funzioni di formattazione di testo per comporre query, query dinamiche assemblate in procedure memorizzate con esecuzione di testo. Gli stessi segnali valgono in ogni linguaggio.` },
      { h: 'Parametri, ORM e identificatori', b: `Le **query parametrizzate** (prepared statement) sono la difesa primaria. Alcune precisazioni:\n\n- Un **ORM** usa di norma query parametrizzate, ma offre quasi sempre anche scorciatoie per «SQL grezzo» o filtri a stringa: se vi si concatenano dati, il problema ritorna.\n- I parametri valgono per i **valori**, non per **nomi di tabelle, colonne o direzione di ordinamento**. Per questi si usa una **lista consentita** di valori noti.\n\n> VULNERABILE: db.execute("SELECT * FROM prodotti ORDER BY " + colonna)\n> CORRETTO: ordinabili = {"nome", "prezzo"}; se colonna non è in ordinabili si usa "nome"; poi si compone la query con il valore già approvato.\n\n- Le **procedure memorizzate** sono sicure solo se non compongono SQL con concatenazione al loro interno.\n\nIn sintesi: parametri per i valori, lista consentita per gli identificativi, mai concatenazione diretta di input.` },
      { h: 'Comandi di sistema, LDAP, NoSQL', b: `Lo stesso principio vale fuori da SQL.\n\n**Comandi del sistema operativo**: se un’applicazione passa dati utente a una shell, l’interprete può trattarli come comandi. Soluzioni: **evitare la shell** usando API dedicate, oppure invocare il programma passando gli **argomenti come elenco separato**, senza interpretazione.\n\n> VULNERABILE: eseguiShell("ping " + host)\n> CORRETTO: eseguiProgramma(["ping", "-c", "1", host_validato]) senza shell, con host controllato da lista o formato\n\n**LDAP**: i filtri di ricerca vanno costruiti con funzioni di **escape** previste dalla libreria o con API parametrizzate.\n\n**NoSQL**: anche senza SQL, query composte da oggetti costruiti a partire dall’input possono essere manipolate. Si convalidano **tipo e forma** dei dati (per esempio, un campo deve essere una stringa, non un oggetto) e si usano operatori fissi lato server.\n\nIn ogni caso: struttura sotto controllo del programma, dati passati come dati.` },
      { h: 'Validazione dell’input: difesa secondaria', b: `La **validazione dell’input** è utile, ma è un livello **secondario**: riduce la superficie d’attacco e blocca dati assurdi, però non sostituisce la separazione tra dati e codice.\n\nBuone pratiche:\n\n- **lista consentita** (allow-list) invece di lista di caratteri vietati: definisci ciò che è ammesso (formato, lunghezza, intervallo, tipo);\n- convalida **lato server**; quella del browser migliora l’esperienza ma non è un controllo di sicurezza;\n- **normalizza** prima di convalidare (codifica, maiuscole/minuscole) per evitare scorciatoie;\n- rifiuta ciò che non è valido invece di tentare di «correggerlo».\n\n> Esempio: un CAP italiano è valido se composto da esattamente 5 cifre; un ID numerico va convertito in intero e confrontato con un intervallo.\n\nAttenzione: un cognome come O’Brien è legittimo. Una validazione che vieta l’apostrofo danneggia gli utenti e non risolve l’injection; la parametrizzazione sì.` },
      { h: 'Minimo privilegio e riduzione del danno', b: `Si assume che qualcosa possa andare storto e si limita il danno.\n\n- **Account di database a minimo privilegio**: l’applicazione web usa un utente che può eseguire solo le operazioni necessarie (per esempio SELECT e INSERT su specifiche tabelle), non il proprietario dello schema, e non può lanciare comandi di amministrazione. Account separati per lettura e scrittura riducono ulteriormente l’impatto.\n- **Nessuna esecuzione di comandi** dal database o dal processo applicativo se non serve.\n- **Messaggi d’errore generici** verso l’utente, dettagli solo nei log interni: gli errori verbosi aiutano chi esplora.\n- **Segmentazione**: il database non deve essere raggiungibile da Internet.\n- **Cifratura e mascheramento** dei dati sensibili, così una fuga ha meno valore.\n\nQuesto principio non sostituisce la parametrizzazione: è la **rete di sicurezza** quando una difesa fallisce.` },
      { h: 'WAF, test e difesa in profondità', b: `Un **WAF** (Web Application Firewall) filtra il traffico HTTP e blocca schemi di richiesta sospetti. È un **livello utile**, soprattutto per protezione temporanea in attesa di correggere il codice, per rilevamento e per limitare il rumore. Ma **non è** la correzione: regole basate su schemi possono dare falsi negativi e falsi positivi, e la vulnerabilità resta nel codice.\n\nProgramma completo di difesa:\n\n1. **Prevenzione primaria**: query parametrizzate, API sicure, liste consentite.\n2. **Validazione** lato server come livello secondario.\n3. **Minimo privilegio** su database e processi.\n4. **Analisi del codice** (SAST) e test dinamici (DAST) in pipeline.\n5. **Revisione del codice** con attenzione alle concatenazioni.\n6. **Monitoraggio** e allarmi su errori anomali di database.\n7. **WAF** come strato aggiuntivo.\n\nRegola da ricordare: la correzione vera è **separare dati e codice**, tutto il resto riduce il rischio residuo.` }
    ],
    exercises: [
      M('Qual è la causa profonda di un’injection?', 'Dati non fidati mescolati al testo di un comando interpretato', ['Uso di HTTPS invece di HTTP', 'Password troppo lunghe', 'Cookie senza scadenza'], 0, 'Struttura e dati viaggiano nello stesso canale: l’interprete non li distingue.'),
      M('Quale snippet è vulnerabile?', 'db.execute("SELECT * FROM utenti WHERE id = " + id)', ['db.execute("SELECT * FROM utenti WHERE id = ?", [id])', 'db.execute("SELECT * FROM utenti WHERE id = :id", {id: id})', 'db.execute(QUERY_FISSA, [id])'], 0, 'La concatenazione di input nel testo SQL è il pattern vulnerabile.'),
      M('Quale correzione è giusta per eseguire il comando «ping» su un host fornito dall’utente?', 'Invocare il programma senza shell con argomenti separati e host validato', ['Concatenare l’host nella stringa e passarla alla shell', 'Cancellare solo gli spazi dall’input', 'Eseguire il comando con privilegi amministrativi'], 0, 'Senza shell non c’è interpretazione dei metacaratteri; la validazione completa la difesa.'),
      fill('Come si chiama la tecnica in cui il testo SQL è fisso e i valori viaggiano separati? (query ...)', ['parametrizzata', 'parametrizzate', 'Parametrizzata'], 'Le query parametrizzate (prepared statement) separano struttura e dati.'),
      M('Un ORM è usato con un metodo di «SQL grezzo» a cui si concatena l’input. Cosa si può dire?', 'È ancora vulnerabile: l’ORM protegge solo se si usano parametri', ['È sicuro perché usa un ORM', 'È sicuro se il database è sul cloud', 'È sicuro se il sito usa HTTPS'], 0, 'La protezione dipende da come si costruisce la query, non dallo strumento.'),
      M('Per scegliere la colonna di ordinamento, quale soluzione è corretta?', 'Confrontarla con una lista consentita di colonne note', ['Passarla come parametro al posto del nome colonna', 'Concatenarla dopo aver tolto gli apici', 'Accettarla se è abbastanza corta'], 0, 'I parametri valgono per i valori, non per gli identificatori: serve una allow-list.'),
      M('Quale account di database è preferibile per l’applicazione web?', 'Utente con soli privilegi necessari su specifiche tabelle', ['L’utente amministratore del database', 'Il proprietario dell’intero schema', 'Un utente condiviso con tutti gli altri servizi'], 0, 'Il minimo privilegio limita il danno se qualcosa va storto.'),
      fill('La validazione lato server basata su cosa è ammesso, anziché su ciò che è vietato, si chiama… (due parole, con trattino o spazio)', ['lista consentita', 'allow-list', 'allowlist', 'allow list', 'whitelist'], 'La lista consentita definisce formati validi e rifiuta il resto.'),
      M('Quale affermazione sul WAF è corretta?', 'È un livello aggiuntivo, non sostituisce la correzione del codice', ['Rende inutili le query parametrizzate', 'Garantisce sicurezza totale', 'Serve solo contro password deboli'], 0, 'Il WAF riduce il rischio ma la vulnerabilità resta nel codice.'),
      order('Ordina i livelli di difesa dal più importante', ['Parametrizzazione', 'poi', 'validazione', 'minimo privilegio', 'monitoraggio e WAF'], 'La prevenzione primaria viene prima di tutto, poi i livelli di contenimento.')
    ],
    test: [
      M('Perché «togliere gli apici» dall’input non basta?', 'Non separa dati e struttura e può essere aggirato o danneggiare dati validi', ['Perché gli apici sono sempre obbligatori', 'Perché il database è lento', 'Perché è vietato per legge'], 0, 'La parametrizzazione risolve alla radice; il filtraggio di caratteri è fragile.'),
      M('Quale versione è corretta per un filtro LDAP con input utente?', 'Usare funzioni di escape o API parametrizzate della libreria', ['Concatenare direttamente il nome utente nel filtro', 'Accettare qualunque carattere', 'Disabilitare il registro eventi'], 0, 'Il filtro va costruito con strumenti che separano i dati.'),
      fill('Un campo che dovrebbe contenere una stringa ma riceve un oggetto è un problema tipico di quale tipo di database? (sigla di cinque lettere)', ['NoSQL', 'nosql', 'Nosql'], 'Nei database NoSQL va validato il tipo oltre al valore.'),
      M('Quale messaggio d’errore verso l’utente è corretto?', 'Messaggio generico, dettagli solo nei log interni', ['Il testo completo dell’errore del database', 'Lo stack trace del server', 'La query SQL che ha fallito'], 0, 'Gli errori verbosi aiutano chi cerca di sfruttare la falla.'),
      M('La validazione lato browser è…', 'utile per l’esperienza d’uso ma non è un controllo di sicurezza', ['sufficiente da sola', 'obbligatoria al posto di quella server', 'sempre più sicura di quella server'], 0, 'Il client può essere aggirato: la validazione vera è sul server.'),
      M('Cosa indica una query SQL con più concatenazioni di variabili esterne durante una revisione?', 'Un probabile punto di injection da correggere con parametri', ['Una query ottimizzata', 'Un uso corretto di prepared statement', 'Un problema solo di prestazioni'], 0, 'È il segnale tipico da cercare in code review.'),
      fill('Il principio per cui l’account applicativo ha solo i permessi indispensabili è il minimo… (una parola)', ['privilegio', 'Privilegio'], 'Minimo privilegio: riduce l’impatto di una compromissione.')
    ]
  });

  /* ---------- 4 · XSS, CSRF e difese ---------- */
  C.addTopic({
    id: 'cyb-xss-csrf-e-difese', subject: 'cyb', stage: 'L3', minutes: 12,
    title: 'XSS, CSRF e difese',
    summary: 'Cross-site scripting, CSRF e clickjacking: come funzionano a livello concettuale e quali difese applicare.',
    objectives: ['Distinguere XSS riflesso, memorizzato e DOM-based', 'Applicare la codifica dell’output in base al contesto e una CSP', 'Proteggere le azioni con SameSite, token anti-CSRF e frame-ancestors'],
    prereq: ['cyb-http-sessioni-e-cookie'],
    pages: [
      { h: 'Che cos’è l’XSS', b: `Il **Cross-Site Scripting (XSS)** si verifica quando un’applicazione inserisce dati non fidati in una pagina web senza trattarli correttamente, così il browser li esegue come **codice** dentro l’origine del sito. Lo script iniettato ha gli stessi diritti della pagina: può leggere contenuti, agire a nome dell’utente, alterare l’interfaccia.\n\nÈ una forma di **injection lato browser**: la causa è la stessa, dati mescolati con il linguaggio che li interpreta (HTML, attributi, JavaScript, URL, CSS).\n\nLa difesa principale non è «filtrare le parole pericolose», ma **codificare l’output** (output encoding) in modo adatto al punto della pagina in cui il dato viene inserito, abbinando difese di contenimento come la **CSP**.\n\nImpatto tipico: furto di sessione (se i cookie non sono HttpOnly), azioni non volute, falsi moduli di login, diffusione di contenuti malevoli. Bastano **un solo punto** non protetto per compromettere l’intero sito.` },
      { h: 'Tre varianti: riflesso, memorizzato, DOM', b: `**XSS riflesso (reflected)**: il dato arriva con la richiesta (parametro dell’URL, modulo) e la risposta lo inserisce subito nella pagina. L’utente deve essere indotto ad aprire un link manipolato.\n\n**XSS memorizzato (stored)**: il dato viene **salvato** (commento, profilo, messaggio) e mostrato a chiunque apra quella pagina. È la variante più grave, perché colpisce molti utenti senza interazione particolare.\n\n**XSS basato su DOM (DOM-based)**: il problema è nel **JavaScript lato client**, che legge una fonte non fidata (URL, frammento, messaggi tra finestre) e la scrive in un punto pericoloso del DOM. Il server può non vedere mai il dato.\n\n> VULNERABILE: elemento.innerHTML = datoUtente\n> CORRETTO: elemento.textContent = datoUtente\n\n**textContent** tratta il valore come testo, mentre **innerHTML** lo interpreta come HTML.` },
      { h: 'Codifica dell’output per contesto', b: `La stessa stringa richiede **codifiche diverse** a seconda del contesto in cui compare:\n\n- **corpo HTML**: codifica delle entità HTML (i caratteri speciali diventano sequenze innocue);\n- **valore di attributo**: codifica per attributi, e **sempre tra virgolette**;\n- **JavaScript**: evitare di inserire dati nel codice; se inevitabile, trasmetterli come JSON sicuro o attributi data-*;\n- **URL**: codifica percentuale per i parametri, controllo dello schema (ammessi solo http e https);\n- **CSS**: evitare dati utente.\n\n> VULNERABILE: template che stampa il commento dell’utente senza codifica\n> CORRETTO: motore di template con **escape automatico** attivo per impostazione predefinita\n\nRegole pratiche: usare framework che applicano l’escape automatico, **non** disattivarlo con funzioni di tipo «raw» o «safe» sui dati utente, e quando serve HTML ricco usare un **sanificatore** consolidato con lista consentita di tag, non espressioni regolari.` },
      { h: 'CSP e Trusted Types', b: `La **Content Security Policy (CSP)** è un’intestazione con cui il server dice al browser **da dove** possono provenire script, stili, immagini e frame. È un livello di **contenimento**: anche se resta una falla di XSS, il browser può rifiutare di eseguire script non autorizzati.\n\n> Esempio di policy rigorosa: Content-Security-Policy: default-src 'self'; script-src 'self' 'nonce-RANDOM'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'\n\nPunti chiave: preferire **nonce** o hash a elenchi di domini; evitare **'unsafe-inline'** e **'unsafe-eval'**; introdurre la policy in modalità **report-only** per vedere cosa si rompe prima di imporla.\n\n**Trusted Types** (concetto): una funzione del browser che impedisce di assegnare **stringhe qualunque** a punti pericolosi come innerHTML; si accettano solo oggetti prodotti da funzioni di sanificazione dichiarate. Così gli XSS DOM-based diventano molto più difficili da introdurre.\n\nLa CSP **integra** la codifica dell’output, non la sostituisce.` },
      { h: 'CSRF: richieste non volute', b: `Il **Cross-Site Request Forgery (CSRF)** sfrutta il fatto che il browser allega **automaticamente** i cookie alle richieste verso un sito. Se un utente è autenticato su un sito e visita una pagina malevola, quest’ultima può indurre il browser a inviare una richiesta di modifica a quel sito: il server la vede arrivare con la sessione valida e la esegue.\n\nL’attaccante **non legge** la risposta (lo impedisce la same-origin policy): fa solo compiere un’azione. Le azioni di modifica dello stato sono dunque il bersaglio.\n\nCondizioni necessarie: autenticazione basata su **cookie inviati automaticamente**, azione prevedibile da replicare, nessuna verifica dell’intenzione dell’utente.\n\nNon è un problema delle API che usano un’intestazione Authorization inserita esplicitamente dal client: quell’intestazione non viene aggiunta automaticamente dal browser. È invece un rischio tipico di applicazioni con sessioni a cookie.` },
      { h: 'Difese anti-CSRF', b: `Difese combinate e complementari:\n\n- **Cookie SameSite** (Lax o Strict): il browser non allega il cookie alle richieste cross-site di modifica. È la prima barriera, ma non la sola.\n- **Token anti-CSRF**: valore imprevedibile legato alla sessione, inserito nei moduli o in un’intestazione e **verificato dal server** a ogni richiesta che modifica lo stato. Una pagina esterna non può conoscerlo.\n- **Verifica di Origin e Referer** sul server come controllo aggiuntivo.\n- **Metodi corretti**: modifiche solo con POST, PUT, PATCH o DELETE, mai con GET.\n- **Ri-autenticazione** per azioni critiche.\n\n> VULNERABILE: il server esegue POST /profilo/email se il cookie di sessione è valido\n> CORRETTO: il server esegue la modifica solo se il cookie è valido **e** il token anti-CSRF ricevuto coincide con quello associato alla sessione\n\nI framework moderni offrono di solito il token in modo integrato: va **attivato** e non escluso per comodità.` },
      { h: 'Clickjacking e frame-ancestors', b: `Il **clickjacking** consiste nell’incorporare un sito legittimo in un **frame** invisibile o camuffato dentro un’altra pagina, inducendo l’utente a cliccare su elementi che non vede davvero (per esempio un pulsante di conferma).\n\nLa difesa è decidere **chi può incorniciare** le proprie pagine:\n\n- intestazione CSP **frame-ancestors**: 'none' vieta qualunque incorporamento; 'self' lo consente solo al sito stesso; un elenco permette origini fidate;\n- l’intestazione più vecchia **X-Frame-Options** (DENY o SAMEORIGIN) resta utile per compatibilità;\n- azioni sensibili richiedono conferma esplicita e, se serve, ri-autenticazione.\n\n> CORRETTO: Content-Security-Policy: frame-ancestors 'none'\n\nRiepilogo difensivo della lezione: **codifica per contesto**, **CSP** e Trusted Types per l’XSS; **SameSite** e **token** per il CSRF; **frame-ancestors** per il clickjacking; **HttpOnly** sui cookie per limitare i danni.` }
    ],
    exercises: [
      M('Quale variante di XSS salva il dato nel sito e colpisce chiunque visiti la pagina?', 'XSS memorizzato (stored)', ['XSS riflesso', 'CSRF', 'Clickjacking'], 0, 'Il dato è conservato e mostrato a molti utenti.'),
      M('Quale riga è vulnerabile a XSS DOM-based?', 'elemento.innerHTML = datoUtente', ['elemento.textContent = datoUtente', 'elemento.setAttribute("data-nome", datoUtente)', 'elemento.append(document.createTextNode(datoUtente))'], 0, 'innerHTML interpreta il valore come HTML, le altre lo trattano come testo.'),
      M('Qual è la difesa principale contro l’XSS?', 'Codifica dell’output adatta al contesto', ['Vietare alcune parole nei campi di input', 'Usare password più lunghe', 'Comprimere le risposte'], 0, 'Il dato va reso innocuo nel punto in cui viene inserito.'),
      M('Quale configurazione di template è corretta?', 'Escape automatico attivo per tutte le variabili', ['Funzione «raw» applicata ai commenti degli utenti', 'Escape disattivato per velocità', 'Escape solo sui campi di ricerca'], 0, 'L’escape automatico riduce la probabilità di errore umano.'),
      fill('Quale intestazione indica al browser da dove possono provenire script e risorse? (sigla di tre lettere)', ['CSP', 'csp'], 'Content Security Policy.'),
      M('Quale policy CSP è più solida per gli script?', "script-src 'self' 'nonce-RANDOM'", ["script-src * 'unsafe-inline'", "script-src 'unsafe-eval' *", "script-src data: *"], 0, 'Il nonce permette solo gli script previsti, senza jolly.'),
      M('Quale difesa è specifica contro il CSRF?', 'Token anti-CSRF verificato dal server con cookie SameSite', ['Output encoding HTML', 'Limite di dimensione dei file', 'Cifratura del database'], 0, 'Il token dimostra che la richiesta nasce dal sito stesso.'),
      M('Quale azione non dovrebbe MAI essere implementata con un GET?', 'Cancellare un account', ['Leggere un articolo', 'Cercare un prodotto', 'Visualizzare un profilo pubblico'], 0, 'Le azioni di modifica devono usare metodi non sicuri e protezioni CSRF.'),
      fill('Quale direttiva CSP impedisce che le pagine vengano incorniciate da altri siti? (una parola con trattino)', ['frame-ancestors', 'Frame-Ancestors'], 'frame-ancestors definisce chi può incorporare la pagina.'),
      order('Ordina le difese per un modulo che modifica lo stato', ['Metodo POST', 'poi', 'cookie SameSite', 'token anti-CSRF', 'verifica server-side'], 'Più livelli concorrono a proteggere l’azione.')
    ],
    test: [
      M('Cosa fa Trusted Types, a livello concettuale?', 'Impedisce di assegnare stringhe qualunque a punti pericolosi del DOM', ['Cifra i cookie', 'Blocca tutti i cookie di terze parti', 'Sostituisce il protocollo HTTPS'], 0, 'Accetta solo oggetti prodotti da funzioni di sanificazione dichiarate.'),
      M('Perché l’attaccante in un CSRF non legge la risposta?', 'La same-origin policy lo impedisce', ['Perché HTTPS cifra la risposta', 'Perché il server la nasconde', 'Perché i cookie sono HttpOnly'], 0, 'Può far eseguire azioni, non leggerne gli esiti.'),
      fill('Il flag del cookie che lo nasconde a JavaScript e limita i danni di un XSS è… (una parola)', ['HttpOnly', 'httponly'], 'HttpOnly impedisce la lettura via document.cookie.'),
      M('Quale intestazione protegge dal clickjacking in modo moderno?', "Content-Security-Policy: frame-ancestors 'none'", ['Cache-Control: no-store', 'Content-Length: 0', 'Accept-Language: it'], 0, 'Impedisce l’incorporamento in frame di altri siti.'),
      M('Quando serve HTML ricco inserito dagli utenti, cosa è meglio fare?', 'Sanificare con una libreria consolidata e lista consentita di tag', ['Usare un’espressione regolare artigianale', 'Inserirlo con innerHTML senza controlli', 'Bloccare solo la parola «script»'], 0, 'Le soluzioni artigianali sono fragili: meglio librerie mantenute.'),
      M('Le API che usano un token inserito esplicitamente dal client nell’intestazione Authorization sono…', 'meno esposte al CSRF, perché il browser non lo allega da solo', ['sempre immuni da qualunque attacco', 'più esposte al CSRF dei cookie', 'vulnerabili solo se usano HTTPS'], 0, 'Il rischio CSRF nasce dall’invio automatico dei cookie.'),
      fill('Quale modalità di CSP permette di osservare le violazioni senza bloccarle? (report-... una parola dopo il trattino)', ['report-only', 'Report-Only'], 'Content-Security-Policy-Report-Only consente di testare la policy.')
    ]
  });

  /* ---------- 5 · Controllo accessi e API ---------- */
  C.addTopic({
    id: 'cyb-controllo-accessi-e-api', subject: 'cyb', stage: 'L3', minutes: 12,
    title: 'Controllo degli accessi e sicurezza delle API',
    summary: 'Autorizzazione lato server, IDOR, RBAC e ABAC, rischi tipici delle API e flussi OAuth2/OIDC.',
    objectives: ['Riconoscere e correggere un problema di controllo degli accessi (IDOR)', 'Distinguere RBAC e ABAC e applicare l’autorizzazione lato server', 'Elencare le difese principali delle API e gli errori comuni in OAuth2/OIDC'],
    prereq: ['cyb-owasp-top10-panoramica', 'cyb-http-sessioni-e-cookie'],
    pages: [
      { h: 'Autenticazione e autorizzazione', b: `Due concetti da non confondere:\n\n- **Autenticazione**: verificare **chi sei** (password, MFA, certificato).\n- **Autorizzazione**: verificare **cosa puoi fare** su una specifica risorsa.\n\nIl **controllo degli accessi violato** (broken access control) è la categoria di rischio più diffusa tra quelle misurate nelle applicazioni web: l’utente è autenticato ma l’applicazione non verifica correttamente i suoi diritti.\n\nPrincipi di base:\n\n- **deny by default**: se non c’è una regola esplicita che consente, si nega;\n- **autorizzazione lato server**, a **ogni richiesta**, per ogni risorsa e azione;\n- **minimo privilegio**;\n- un’unica componente centrale di verifica, non controlli sparsi e ripetuti a mano;\n- i controlli nell’interfaccia (pulsante nascosto) sono solo **comodità**, non sicurezza: la richiesta può essere inviata comunque.\n\nUn menu che nasconde la funzione amministrativa non impedisce a un utente di richiamarla direttamente.` },
      { h: 'IDOR: riferimenti diretti non protetti', b: `L’**IDOR** (Insecure Direct Object Reference) accade quando l’applicazione usa un identificatore fornito dal client (per esempio un numero nell’URL) per recuperare una risorsa **senza verificare** che appartenga all’utente che la richiede.\n\n> VULNERABILE:\n> ordine = db.trova(ordini, id_ricevuto)\n> restituisci ordine\n\n> CORRETTO:\n> ordine = db.trova(ordini, id_ricevuto)\n> se ordine.proprietario diverso da utente_sessione.id → rispondi 403 (o 404)\n\nUn’alternativa ancora migliore è **includere il proprietario nella query**, così la risorsa altrui non viene nemmeno letta:\n\n> db.trova(ordini, id = id_ricevuto E proprietario = utente_sessione.id)\n\nLe sole **ID non prevedibili** (UUID) non sono una difesa sufficiente: aiutano contro l’enumerazione, ma il controllo di proprietà resta indispensabile. L’identità dell’utente deve provenire dalla **sessione sul server**, mai da un campo inviato dal client.` },
      { h: 'RBAC, ABAC e altri modelli', b: `**RBAC** (Role-Based Access Control): i permessi sono assegnati a **ruoli** (utente, redattore, amministratore) e gli utenti ricevono i ruoli. È semplice da amministrare e verificare, ma può diventare rigido o dare origine a una moltiplicazione di ruoli.\n\n**ABAC** (Attribute-Based Access Control): la decisione dipende da **attributi** di utente, risorsa e contesto (reparto, proprietà del documento, orario, livello di rischio). È molto flessibile, ma richiede politiche più curate e testate.\n\nSpesso si **combinano**: il ruolo stabilisce la capacità generale, gli attributi affinano la regola («il medico può leggere cartelle dei **propri** pazienti»).\n\nBuone pratiche: separare la **politica** (regole) dal **codice**, registrare le decisioni importanti, rivedere i permessi periodicamente, evitare ruoli generici onnipotenti, e testare in modo automatico i casi **negativi** (l’utente A non deve accedere ai dati di B).\n\nVa verificato anche l’accesso **orizzontale** (tra pari) e **verticale** (verso ruoli superiori).` },
      { h: 'API: i rischi tipici', b: `Le **API** espongono funzioni e dati direttamente, quindi gli errori si vedono subito. Rischi ricorrenti:\n\n- **Autenticazione debole o assente** su alcuni endpoint dimenticati.\n- **Autorizzazione a livello di oggetto e di funzione** mancante (IDOR, funzioni amministrative accessibili a tutti).\n- **Esposizione eccessiva di dati**: l’API restituisce l’intero oggetto e lascia al client il compito di filtrare. Si risponde con **DTO** o schemi di risposta che includono solo i campi necessari.\n- **Mass assignment**: l’API copia in blocco i campi ricevuti nel modello, permettendo di modificare campi riservati (ruolo, saldo).\n- **Mancanza di limiti**: nessun controllo su frequenza e dimensione delle richieste.\n- **Inventario incompleto**: versioni vecchie o endpoint di test ancora attivi.\n\n> VULNERABILE: utente.aggiorna(corpo_richiesta)\n> CORRETTO: utente.aggiorna({ nome: corpo.nome, email: corpo.email }) con campi ammessi in lista consentita` },
      { h: 'Difese delle API', b: `Un insieme coerente di difese:\n\n- **Autenticazione forte** per ogni endpoint non pubblico, con token a scadenza breve.\n- **Autorizzazione** a ogni richiesta, per oggetto e per funzione.\n- **Validazione con schema** (per esempio JSON Schema o OpenAPI): tipi, lunghezze, formati, campi ammessi; **rifiuto** di ciò che non rispetta lo schema.\n- **Rate limiting** e quote per client, per rallentare abusi, automazioni e tentativi ripetuti; risposta **429**. Limiti anche su dimensione del corpo e paginazione.\n- **Risposte minime**: solo i campi richiesti, errori generici.\n- **API gateway**: punto centrale per autenticazione, limiti di frequenza, registrazione, filtri e instradamento. Utile, ma **non sostituisce** i controlli nel servizio: un servizio raggiungibile per altre vie deve rimanere protetto.\n- **TLS** sempre; **CORS** con lista chiusa.\n- **Inventario e versionamento** delle API, con dismissione di quelle vecchie.\n\nIl gateway è un livello, non la sicurezza intera.` },
      { h: 'OAuth 2.0 e OpenID Connect', b: `**OAuth 2.0** è un framework di **autorizzazione delegata**: un’applicazione ottiene un **access token** con ambiti (scope) limitati per accedere a risorse di un utente, senza conoscerne la password. **OpenID Connect (OIDC)** aggiunge un livello di **autenticazione**: restituisce un **ID token** che attesta l’identità dell’utente.\n\nFlusso raccomandato per applicazioni web e mobili: **Authorization Code con PKCE**: l’app reindirizza al provider, l’utente si autentica e acconsente, l’app riceve un **codice** di breve durata e lo scambia con i token. PKCE lega lo scambio al client che lo ha iniziato.\n\nI flussi più vecchi, come **Implicit** e **Resource Owner Password**, sono sconsigliati.\n\nRuoli: utente (resource owner), client, server di autorizzazione, server delle risorse.\n\nConcetti da distinguere: **OAuth non dice chi sei** (serve OIDC per questo); l’access token autorizza, l’ID token identifica.` },
      { h: 'Errori comuni in OAuth/OIDC', b: `Errori frequenti, a livello concettuale:\n\n- **redirect URI** troppo permissivi o con jolly: il codice può finire a un destinatario sbagliato. Va fatto un confronto **esatto** con URI registrati;\n- assenza del parametro **state** (o nonce in OIDC): serve a legare richiesta e risposta e a prevenire richieste forgiate;\n- **PKCE** non usato nei client pubblici;\n- **scope eccessivi**: richiedere più permessi del necessario;\n- **token validati male**: firma, emittente (iss), destinatario (aud), scadenza (exp) vanno sempre controllati dal server che li riceve;\n- uso dell’**ID token** come access token verso le API;\n- token in luoghi esposti (URL, localStorage, log);\n- segreti del client incorporati in app pubbliche;\n- **refresh token** senza rotazione né revoca.\n\n> Regola: usa librerie e provider consolidati, registra i redirect URI esatti, richiedi lo scopo minimo e valida ogni token ricevuto.` }
    ],
    exercises: [
      M('Quale affermazione sull’autorizzazione è corretta?', 'Va verificata sul server a ogni richiesta', ['È sufficiente nascondere il pulsante nell’interfaccia', 'Basta controllarla al login', 'Si può affidare al client'], 0, 'Il client è controllato dall’utente: solo il server è affidabile.'),
      M('Quale snippet è vulnerabile a IDOR?', 'ordine = trova(id_ricevuto); restituisci ordine', ['ordine = trova(id_ricevuto, proprietario = utente_sessione.id)', 'se ordine.proprietario diverso da utente_sessione.id → 403', 'si usa l’identità presa dalla sessione sul server'], 0, 'Manca la verifica di proprietà della risorsa.'),
      M('Quale correzione è la più solida per un IDOR?', 'Includere il proprietario (dalla sessione) nella query e rifiutare se assente', ['Usare ID molto lunghi e casuali come unica difesa', 'Nascondere il link nella pagina', 'Cifrare l’ID nell’URL e non controllare altro'], 0, 'ID non prevedibili aiutano ma non sostituiscono il controllo di proprietà.'),
      fill('Il principio per cui tutto è negato salvo regola esplicita si chiama deny by … (una parola)', ['default', 'Default'], 'Deny by default.'),
      M('Quale modello decide in base ad attributi di utente, risorsa e contesto?', 'ABAC', ['RBAC', 'MFA', 'CORS'], 0, 'ABAC usa attributi; RBAC usa ruoli.'),
      M('Quale riga è vulnerabile a mass assignment?', 'utente.aggiorna(corpo_richiesta)', ['utente.aggiorna({nome: corpo.nome, email: corpo.email})', 'schema.valida(corpo) con campi ammessi in lista', 'DTO di ingresso con soli campi modificabili'], 0, 'Copiare in blocco permette di modificare campi riservati come il ruolo.'),
      M('Un endpoint restituisce l’intero oggetto utente, incluso l’hash della password. Che problema è?', 'Esposizione eccessiva di dati: servono risposte minime con DTO', ['Mass assignment', 'CSRF', 'Clickjacking'], 0, 'Si rispondono solo i campi necessari, non l’intero oggetto.'),
      fill('Quale codice di stato HTTP si restituisce quando un client supera i limiti di richieste? (tre cifre)', ['429'], '429 Too Many Requests.'),
      M('Quale flusso OAuth2 è consigliato per le app web e mobili?', 'Authorization Code con PKCE', ['Implicit', 'Resource Owner Password Credentials', 'Condivisione della password con il client'], 0, 'I flussi più vecchi sono sconsigliati.'),
      order('Ordina i passi del flusso Authorization Code', ['Reindirizzamento al provider', 'poi', 'login e consenso', 'codice di breve durata', 'scambio con i token'], 'Il codice è scambiato con i token da parte del client.')
    ],
    test: [
      M('Cosa distingue OIDC da OAuth 2.0?', 'OIDC aggiunge l’autenticazione con un ID token', ['OIDC non usa token', 'OIDC sostituisce HTTPS', 'OIDC è solo per le stampanti'], 0, 'OAuth autorizza, OIDC identifica.'),
      M('Quale configurazione dei redirect URI è corretta?', 'Confronto esatto con URI registrati in precedenza', ['Pattern con jolly sull’intero dominio', 'Qualunque URI ricevuto nella richiesta', 'Solo il nome dell’host senza percorso'], 0, 'I jolly consentono di dirottare il codice verso destinazioni sbagliate.'),
      fill('Quale parametro OAuth lega la richiesta alla risposta e aiuta contro le richieste forgiate? (una parola)', ['state', 'State'], 'Il parametro state viene verificato al ritorno.'),
      M('Un API gateway…', 'è un livello utile ma non sostituisce i controlli nel servizio', ['rende inutile l’autorizzazione nei servizi', 'elimina ogni vulnerabilità', 'serve solo per i colori dell’interfaccia'], 0, 'Se il servizio è raggiungibile per altre vie deve restare protetto.'),
      M('Perché i controlli solo nell’interfaccia non bastano?', 'La richiesta può essere inviata direttamente senza passare dall’interfaccia', ['Perché i browser sono lenti', 'Perché le interfacce sono cifrate', 'Perché i pulsanti non funzionano'], 0, 'L’interfaccia non è un confine di sicurezza.'),
      M('Quale validazione è preferibile per un’API?', 'Schema che definisce campi, tipi e limiti, con rifiuto del resto', ['Accettare qualsiasi campo ricevuto', 'Controllare solo la lunghezza totale del corpo', 'Fidarsi del client'], 0, 'La validazione con schema rende espliciti i campi ammessi.'),
      fill('L’accesso a dati di un altro utente di pari livello è un accesso … (orizzontale o verticale?)', ['orizzontale', 'Orizzontale'], 'Tra pari è orizzontale; verso ruoli superiori è verticale.')
    ]
  });

  /* ---------- 6 · SDLC sicuro e supply chain ---------- */
  C.addTopic({
    id: 'cyb-sdlc-sicuro-e-supply-chain', subject: 'cyb', stage: 'L3', minutes: 12,
    title: 'SDLC sicuro e supply chain',
    summary: 'Integrare la sicurezza nel ciclo di sviluppo: modellazione delle minacce, revisione, analisi automatiche, dipendenze, build firmate e log.',
    objectives: ['Collocare le attività di sicurezza nelle fasi del ciclo di sviluppo', 'Distinguere SAST, DAST, IAST e SCA e il ruolo di SBOM e firme', 'Proteggere segreti, pipeline CI/CD e log senza esporre informazioni'],
    prereq: ['cyb-owasp-top10-panoramica'],
    pages: [
      { h: 'Secure SDLC e shift-left', b: `Un **ciclo di sviluppo sicuro** (secure SDLC) inserisce attività di sicurezza in **ogni fase**, non solo alla fine. Il principio **shift-left** è anticipare i controlli: correggere un difetto in progettazione costa molto meno che in produzione.\n\nFasi e attività tipiche:\n\n- **Requisiti**: requisiti di sicurezza e privacy, classificazione dei dati.\n- **Progettazione**: modellazione delle minacce, scelta di schemi sicuri.\n- **Implementazione**: standard di codifica, revisione del codice, analisi statica.\n- **Test**: test dinamici, analisi delle dipendenze, test dei casi di abuso.\n- **Rilascio**: build firmata, configurazioni hardenizzate, controlli di conformità.\n- **Operatività**: monitoraggio, gestione delle vulnerabilità, risposta agli incidenti.\n\nModelli di riferimento: **OWASP SAMM**, **BSIMM**, il framework **NIST SSDF**. Sono strumenti per misurare e far crescere la maturità, non checklist da applicare in blocco.\n\nLa sicurezza è una responsabilità **di tutto il team**, non solo di un reparto separato.` },
      { h: 'Threat modelling in fase di progetto', b: `La **modellazione delle minacce** è un esercizio strutturato per chiedersi, **prima di scrivere codice**, cosa può andare storto. Quattro domande guida:\n\n1. **Cosa stiamo costruendo?** (diagramma dei flussi di dati, confini di fiducia)\n2. **Cosa può andare storto?** (minacce)\n3. **Cosa facciamo al riguardo?** (mitigazioni)\n4. **Abbiamo fatto un buon lavoro?** (verifica)\n\nUn metodo classico per classificare le minacce è **STRIDE**: Spoofing (furto di identità), Tampering (manomissione), Repudiation (ripudio), Information disclosure (divulgazione), Denial of service, Elevation of privilege.\n\n> Esempio: un diagramma mostra che il servizio di pagamento riceve dati da un’app mobile. Il confine di fiducia sta tra app e server: tutto ciò che entra va validato e autorizzato.\n\nSi ottiene un elenco di rischi con priorità e responsabili, da rivedere quando l’architettura cambia. Si parte anche dai **casi di abuso**, non solo dai casi d’uso.` },
      { h: 'Revisione del codice: checklist', b: `La **code review** è un controllo umano efficace, soprattutto con una checklist orientata alla sicurezza. Domande utili:\n\n- **Input**: ogni dato esterno è validato (tipo, lunghezza, formato)?\n- **Query e comandi**: parametri invece di concatenazioni?\n- **Output**: codifica adatta al contesto? Escape automatico attivo?\n- **Autorizzazione**: controllo di proprietà e di ruolo sul server, deny by default?\n- **Autenticazione e sessioni**: rigenerazione ID, cookie con flag, scadenze?\n- **Segreti**: nessuna chiave o password nel codice o nei log?\n- **Crittografia**: algoritmi e librerie standard, niente soluzioni fatte in casa?\n- **Errori**: messaggi generici verso l’utente, dettagli solo nei log?\n- **Dipendenze**: nuove librerie giustificate, mantenute e senza vulnerabilità note?\n- **Test**: ci sono test dei casi negativi?\n\nRegole: revisioni piccole e frequenti, almeno un secondo revisore, e i controlli di sicurezza in un elenco condiviso del team.` },
      { h: 'SAST, DAST, IAST e SCA', b: `Quattro famiglie di strumenti automatici, complementari:\n\n- **SAST** (Static Application Security Testing): analizza il **codice sorgente** senza eseguirlo. Individua pattern rischiosi presto, ma può dare falsi positivi e non vede problemi di configurazione.\n- **DAST** (Dynamic Application Security Testing): prova l’applicazione **in esecuzione** dall’esterno, come farebbe un utente. Trova problemi di configurazione e di comportamento, ma non indica la riga di codice.\n- **IAST** (Interactive Application Security Testing): usa un **agente** dentro l’applicazione durante i test e combina visibilità del codice e comportamento reale.\n- **SCA** (Software Composition Analysis): analizza le **dipendenze** e segnala componenti con vulnerabilità note o licenze problematiche.\n\nNessuno strumento basta da solo. L’uso corretto prevede: integrazione nella pipeline, **triage** dei risultati, soglie che bloccano il rilascio per i problemi gravi, e correzione tracciata. Un report ignorato non protegge.` },
      { h: 'Segreti e dipendenze', b: `**Segreti** (chiavi API, password, certificati, token) non devono mai finire nel codice sorgente né nella cronologia del repository.\n\n- **Secrets scanning**: strumenti che cercano segreti nei commit, anche prima del push (pre-commit) e nell’intera cronologia.\n- Se un segreto è finito nel repository, va **revocato e ruotato** subito: cancellarlo dal codice non basta, la cronologia lo conserva.\n- Archivio dedicato (**secret manager**), permessi minimi, rotazione periodica, segreti diversi per ambiente.\n\n> VULNERABILE: chiave_api = "valore-incorporato-nel-codice"\n> CORRETTO: chiave_api = leggi_da_gestore_segreti("pagamenti/chiave") con accesso limitato al servizio\n\n**Dipendenze**: la maggior parte del codice di un’applicazione moderna viene da terzi. Rischi: vulnerabilità note, pacchetti abbandonati, **dipendenze transitive**, nomi ingannevoli (typosquatting) e confusione tra repository interni ed esterni. Misure: versioni **bloccate** con file di lock, poche dipendenze, verifica dell’origine, aggiornamenti regolari automatizzati.` },
      { h: 'SBOM, firme e CI/CD', b: `La **SBOM** (Software Bill of Materials) è l’**elenco dei componenti** di un software con nomi e versioni (formati comuni: CycloneDX, SPDX). Quando emerge una nuova vulnerabilità, permette di rispondere subito alla domanda «siamo esposti?».\n\nLa **firma delle build** (firma di artefatti e immagini, con strumenti come Sigstore/cosign) garantisce **origine e integrità**: chi distribuisce può verificare che l’artefatto provenga davvero dalla pipeline attesa e non sia stato alterato. Concetti correlati: **build riproducibili** e **provenienza** (SLSA).\n\nIrrobustire la **pipeline CI/CD**:\n\n- permessi **minimi** per i job e token a breve durata;\n- segreti non esposti ai build di richieste esterne;\n- branch protetti e revisione obbligatoria prima della fusione;\n- versioni delle azioni di terze parti **bloccate** (per hash);\n- runner isolati ed effimeri;\n- registro dei cambiamenti e verifica degli artefatti prima del rilascio.\n\nLa pipeline è un bersaglio: chi la controlla può inserire codice in produzione.` },
      { h: 'Log ed errori senza fughe di informazioni', b: `I **log** sono indispensabili per rilevare e analizzare incidenti, ma sono anche una fonte di fuga di informazioni.\n\nDa registrare: accessi riusciti e falliti, errori di autorizzazione, modifiche a permessi e dati critici, errori di validazione ripetuti, eventi amministrativi. Ogni voce ha **data e ora affidabili**, identificativo di utente e origine, esito.\n\nDa **non** registrare in chiaro: password, token, chiavi, numeri di carta, dati personali non necessari. Neutralizzare anche i dati utente nei messaggi di log (a capo e caratteri speciali), per evitare falsificazione delle righe.\n\n**Gestione degli errori**: all’utente un messaggio **generico** e un codice di riferimento; i dettagli (stack trace, query, percorsi) solo nei log interni. Modalità debug disattivata in produzione.\n\n> VULNERABILE: risposta con stack trace completo e testo della query\n> CORRETTO: «Si è verificato un errore. Codice: 7F3A» e dettagli nel log protetto\n\nI log vanno **centralizzati**, protetti da modifiche, conservati per un tempo definito e collegati ad **allarmi** e a una procedura di risposta.` }
    ],
    exercises: [
      M('Cosa significa «shift-left» nel ciclo di sviluppo?', 'Anticipare i controlli di sicurezza alle prime fasi', ['Spostare i test dopo il rilascio', 'Eliminare la fase di progettazione', 'Affidare la sicurezza solo al reparto operativo'], 0, 'Correggere presto costa molto meno.'),
      M('Quale strumento analizza il codice sorgente senza eseguirlo?', 'SAST', ['DAST', 'SCA', 'WAF'], 0, 'Static Application Security Testing.'),
      M('Quale strumento segnala dipendenze con vulnerabilità note?', 'SCA', ['SAST', 'DAST', 'CSP'], 0, 'Software Composition Analysis.'),
      fill('Come si chiama l’elenco dei componenti di un software con le versioni? (sigla di quattro lettere)', ['SBOM', 'sbom'], 'Software Bill of Materials.'),
      M('Quale snippet gestisce correttamente un segreto?', 'chiave = leggi_da_gestore_segreti("pagamenti/chiave")', ['chiave = "valore-incorporato-nel-codice"', 'chiave scritta in un commento del repository', 'chiave inviata nel parametro dell’URL'], 0, 'Il segreto non deve stare nel codice né nella cronologia.'),
      M('Una chiave è stata pubblicata per errore in un repository. Cosa fare?', 'Revocarla e ruotarla subito, poi rimuoverla', ['Cancellare il file e basta', 'Aspettare che qualcuno la usi', 'Spostare il repository in privato e non fare altro'], 0, 'La cronologia conserva il segreto: va considerato compromesso.'),
      M('Quale risposta di errore verso l’utente è corretta?', '«Errore interno. Codice di riferimento: 7F3A»', ['Stack trace completo con percorsi dei file', 'Testo della query fallita', 'Versione del server e del database'], 0, 'Dettagli solo nei log interni.'),
      fill('Quale metodo di modellazione delle minacce usa le categorie Spoofing, Tampering, Repudiation...? (sei lettere)', ['STRIDE', 'stride', 'Stride'], 'STRIDE classifica le minacce in sei categorie.'),
      M('Quale misura riduce il rischio nella pipeline CI/CD?', 'Permessi minimi per i job e versioni di terze parti bloccate', ['Un unico token con diritti amministrativi per tutti', 'Eseguire i job con segreti anche per codice esterno', 'Usare sempre l’ultima versione senza controllo'], 0, 'Minimo privilegio e verifica della provenienza proteggono la catena.'),
      order('Ordina le fasi del ciclo di sviluppo sicuro', ['Requisiti', 'poi', 'progettazione con minacce', 'implementazione e test', 'rilascio e operatività'], 'La sicurezza accompagna ogni fase.')
    ],
    test: [
      M('A cosa serve la firma di una build?', 'Garantire origine e integrità dell’artefatto', ['Ridurre le dimensioni del file', 'Velocizzare l’esecuzione', 'Cifrare il database'], 0, 'Chi la riceve può verificare che non sia stata alterata.'),
      M('Quale vantaggio ha il DAST rispetto al SAST?', 'Prova l’applicazione in esecuzione e vede problemi di configurazione', ['Indica sempre la riga di codice difettosa', 'Non richiede un’applicazione in esecuzione', 'Sostituisce la revisione del codice'], 0, 'DAST agisce dall’esterno sul sistema reale.'),
      fill('Quale tipo di dipendenza non è dichiarata direttamente ma arriva da un’altra libreria? (dipendenza ...)', ['transitiva', 'Transitiva'], 'Le dipendenze transitive allargano la superficie d’attacco.'),
      M('Cosa NON va scritto nei log in chiaro?', 'Password e token di sessione', ['Data e ora dell’evento', 'Esito di un accesso', 'Identificativo dell’operazione'], 0, 'I segreti nei log si trasformano in una fuga di informazioni.'),
      M('Cosa si ottiene con la modellazione delle minacce?', 'Un elenco prioritario di rischi e mitigazioni prima di scrivere il codice', ['L’eliminazione definitiva di ogni vulnerabilità', 'Una licenza software', 'Una build più piccola'], 0, 'Aiuta a progettare controlli adeguati fin dall’inizio.'),
      M('Perché è utile bloccare le versioni delle dipendenze con un file di lock?', 'Rende ripetibili le build e controllabili gli aggiornamenti', ['Perché impedisce ogni aggiornamento per sempre', 'Perché cifra il codice', 'Perché elimina le vulnerabilità'], 0, 'Si sa esattamente cosa si distribuisce e si aggiorna in modo consapevole.'),
      fill('Il rischio di pacchetti con nomi quasi identici a quelli noti si chiama … (una parola inglese, nove lettere iniziali typo...)', ['typosquatting', 'Typosquatting'], 'Si evita verificando l’origine e il nome dei pacchetti.')
    ]
  });
})(window.ST = window.ST || {});
